}

const jobsOnly = items.filter(function(it) { return it.type === 'job' && it.link; });

return jobsOnly.map(function(it) {
  return {
    json: {
      company: it.company_or_source || '',
      email: it.email || '',
      job_title: it.title || '',
      link: it.link || '',
      searched_for: profile.job_search_query || '',
      date_found: new Date().toISOString().slice(0, 10),
      country: country,
      chat_id: chatId
    }
  };
});

const items = $('Shape Items for Scoring').first().json.items || [];

let seen = [];
try {
  seen = $('Load Seen Jobs').all()
    .map(function(i) { return i.json.job_link; })
    .filter(Boolean);
} catch (e) { seen = []; }
const seenSet = new Set(seen);

const fresh = items.filter(function(it) {
  if (it.type !== 'job') return true;
  return !seenSet.has(it.link);
});

let cv = '';
try { cv = $('Load CV').first().json.cv_text || ''; } catch (e) { cv = ''; }
try {
  if ($('Prepare Web Query').isExecuted) {
    const webCv = $('Prepare Web Query').first().json.cv_text;
    if (webCv && webCv.length > 50) { cv = webCv; }
  }
} catch (e) {}

return [{ json: {
  items: fresh,
  cv_text: cv,
  has_cv: cv.length > 50,
  skipped_seen: items.length - fresh.length
} }];

const body = $json.body || {};
const category = (body.category || '').trim();
const prompt = (body.prompt || '').trim();
const company = (body.company || '').trim();
const interests = (body.interests || '').trim();
const city = (body.city || '').trim();
const countryCode = ((body.country_code || 'us').trim() || 'us').toLowerCase();
const countryName = (body.country_name || '').trim();
const cvText = (body.cv_text || '').trim();
const sessionId = (body.session_id || 'web-anon').trim();
const wantsInternship = body.internship === true;

const allowedDates = ['all', 'today', '3days', 'week', 'month'];
let datePosted = (body.date_posted || 'month').trim();
if (allowedDates.indexOf(datePosted) === -1) { datePosted = 'month'; }

const remoteOnly = body.remote_only === true;
let employmentTypes = (body.employment_types || '').trim() || 'FULLTIME,CONTRACTOR,PARTTIME,INTERN';
if (wantsInternship) {
  employmentTypes = 'FULLTIME,PARTTIME,INTERN,CONTRACTOR';
}

const role = [category, prompt].filter(Boolean).join(' ');
let searchQuery;
if (company) {
  searchQuery = role ? (role + ' at ' + company) : (company + ' jobs');
} else {
  searchQuery = role || interests || 'jobs';
}

const location = remoteOnly ? 'Remote' : (city || countryName || 'Remote');

let interestProfile = [prompt, interests].filter(Boolean).join('. Also interested in: ') || category || 'General interest';
if (company) {
  interestProfile += '. The candidate specifically wants roles at ' + company + ' - ONLY include jobs where the employer is actually ' + company + '. Exclude any result from a different company.';
}
if (wantsInternship) {
  interestProfile += '. IMPORTANT: the candidate is specifically looking for an internship or alternance/apprenticeship contract (a French work-study program combining study and paid work at a company), not a standard full-time role. Prioritize postings that mention internship, apprenticeship, alternance, stage, work-study, or co-op, even if the listing is formally tagged as full-time or part-time - alternance roles are frequently mis-tagged by job boards. Exclude senior or experienced-only roles.';
}

return [{ json: {
