  job_search_query: searchQuery,
  job_location: location,
  job_country_code: countryCode,
  country_name: countryName || countryCode.toUpperCase(),
  date_posted: datePosted,
  remote_only: remoteOnly,
  employment_types: employmentTypes,
  wants_internship: wantsInternship,
  company: company,
  cv_text: cvText.slice(0, 12000),
