  const cleaned = raw.replace(/```json|```/g, '').trim();
  try { items = JSON.parse(cleaned); } catch (e) { items = []; }
  if (!Array.isArray(items)) { items = []; }
}

return [{ json: {
  items: items,
  skipped_seen: skipped,
  has_cv: hasCv,
  linkedin_url: linkedInUrl,
  searched_for: profile.job_search_query || ''
} }];

const exec = $json.execution || {};
const wf = $json.workflow || {};
const err = exec.error || {};

const nodeName = err.node && err.node.name ? err.node.name : 'unknown node';
const msg = err.message || 'no message';
const when = new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC';

const text = 'Workflow error\n\n' +
  'Workflow: ' + (wf.name || 'unknown') + '\n' +
  'Node: ' + nodeName + '\n' +
  'Error: ' + msg + '\n' +
  'Time: ' + when + '\n\n' +
  'Check n8n Executions for full details.';

return [{ json: { message: text } }];
